def game_score(points: str) -> str:
    names = {0: "0", 1: "15", 2: "30", 3: "40"}
    a = 0
    b = 0
    for p in points:
        if p == "A":
            a += 1
        elif p == "B":
            b += 1
        if a == 4:
            return "Game A"
        if b == 4:
            return "Game B"
    return f"{names[a]}-{names[b]}"
